import collections

def transform(grid):
    H = len(grid)
    W = len(grid[0])
    visited = set()
    result = [[0] * W for _ in range(H)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r, c) not in visited:
                comp_pixels = []
                q = [(r, c)]
                visited.add((r, c))
                head = 0
                while head < len(q):
                    cr, cc = q[head]
                    head += 1
                    comp_pixels.append((cr, cc, grid[cr][cc]))
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] != 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                q.append((nr, nc))
                counts = collections.Counter(p[2] for p in comp_pixels)
                has_target = any(p == 1 or p == 8 for _, _, p in comp_pixels)
                if has_target:
                    mode = max(counts, key=counts.get)
                    for pr, pc, _ in comp_pixels:
                        result[pr][pc] = mode
                else:
                    for pr, pc, _ in comp_pixels:
                        result[pr][pc] = 0
    return result
