import collections

def transform(grid):
    H = len(grid)
    W = len(grid[0])
    vis = set()
    result = [[0] * W for _ in range(H)]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r, c) not in vis:
                comp = []
                queue = [(r, c)]
                vis.add((r, c))
                idx = 0
                while idx < len(queue):
                    cr, cc = queue[idx]
                    idx += 1
                    val = grid[cr][cc]
                    comp.append((cr, cc, val))
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if grid[nr][nc] != 0 and (nr, nc) not in vis:
                                vis.add((nr, nc))
                                queue.append((nr, nc))

                counts = collections.Counter(p[2] for p in comp)
                mode = counts.most_common(1)[0][0]

                for cr, cc, val in comp:
                    result[cr][cc] = mode

    return result
